const incoming=$input.first().json;
if(incoming.body?.recovery_token!==undefined){
 const fs=require('fs'),b=incoming.body;
 const key=fs.readFileSync('/files/.telegram-ui/comfy-control.key','utf8').trim();
 if(!/^[a-f0-9]{64}$/.test(key)||incoming.headers?.['x-n8n-recovery-key']!==key)throw new Error('Recovery authorization required.');
 if(Object.keys(b).some(k=>!['request_id','recovery_token'].includes(k))||!/^tg-0-[0-9]+$/.test(b.request_id??''))throw new Error('Invalid recovery request.');
 const j=JSON.parse(fs.readFileSync('/files/.telegram-ui/scheduler/jobs/'+b.request_id+'.json','utf8'));
 if(j.cancel_requested||j.cleared_at||j.recovery?.ticket!==b.recovery_token)throw new Error('Recovery ticket expired or cancelled.');
 if(!Number.isSafeInteger(j.request?.seed))throw new Error('Original seed is missing. Nothing was regenerated.');
 return [{json:{...j.request,recovery_token:b.recovery_token,resume_plan:j.recovery.plan}}];
}

const body=$input.first().json.body;
if(!body||typeof body!=='object'||Array.isArray(body))throw new Error('JSON body is required.');
const allowed=new Set(['request_id','image','prompt','negative_prompt','duration_seconds','aspect_ratio']);
if(Object.keys(body).some(k=>!allowed.has(k)))throw new Error('Unexpected request fields.');
if(typeof body.image!=='string'||body.image.length>180||!/^[A-Za-z0-9][A-Za-z0-9_-]*\.(png|jpe?g|webp)$/i.test(body.image))throw new Error('Use an image basename, not a path.');
if(typeof body.prompt!=='string'||!body.prompt.trim()||body.prompt.length>3000)throw new Error('prompt: 1–3000 characters.');
if(body.negative_prompt!==undefined&&(typeof body.negative_prompt!=='string'||body.negative_prompt.length>1000))throw new Error('negative_prompt: at most 1000 characters.');
if(typeof body.duration_seconds!=='number'||![2,4,6,8,10].includes(body.duration_seconds))throw new Error('duration_seconds must be 2, 4, 6, 8 or 10.');
if(body.aspect_ratio!==undefined&&!['9:16','16:9'].includes(body.aspect_ratio))throw new Error('aspect_ratio must be 9:16 or 16:9.');
const id=body.request_id??`video-${Date.now()}`;
if(typeof id!=='string'||!/^[A-Za-z0-9_-]{1,80}$/.test(id))throw new Error('Invalid request_id.');
return [{json:{request_id:id,...(body.aspect_ratio===undefined?{}:{aspect_ratio:body.aspect_ratio}),image:body.image,image_path:'/files/current/'+body.image,upload_name:body.image.replace(/\.[^.]+$/, '')===id?body.image:id+'_'+body.image,prompt:body.prompt.trim(),negative_prompt:(body.negative_prompt??'').trim(),duration_seconds:body.duration_seconds,frame_rate:30,seed:Math.floor(Math.random()*4294967296)}}];

// Docker incarnation: a restart gets a new mutex namespace. Old empty locks are not stolen.
const RUNTIME=(()=>{const f=require('fs');try{
 const boot=f.readFileSync('/proc/sys/kernel/random/boot_id','utf8').trim();
 const stat=f.readFileSync('/proc/1/stat','utf8');const fields=stat.slice(stat.lastIndexOf(')')+2).split(' ');
 if(!/^[a-f0-9-]{36}$/.test(boot)||!/^\d+$/.test(fields[19]))throw Error();return boot+'-'+fields[19];
}catch(_){throw new Error('Recovery requires the configured Linux Docker container (/proc readable).');}})();

// Shared, embedded in Code nodes. Requires only built-in fs and shared /files.
const S = (() => {
  const fs=require('fs');
  const root='/files/.telegram-ui/scheduler', jobs=root+'/jobs', control=root+'/control.json';
  fs.mkdirSync(jobs,{recursive:true,mode:0o700});
  const execution=String($execution.id);
  const valid=id=>typeof id==='string'&&/^[A-Za-z0-9_-]{1,80}$/.test(id);
  const jobPath=id=>{if(!valid(id))throw new Error('Invalid request_id');return jobs+'/'+id+'.json';};
  const read=(p,fallback)=>fs.existsSync(p)?JSON.parse(fs.readFileSync(p,'utf8')):fallback;
  function write(p,value){
    const temp=p+'.tmp-'+execution+'-'+Date.now();let fd;
    try{fd=fs.openSync(temp,'wx',0o600);fs.writeFileSync(fd,JSON.stringify(value));fs.fsyncSync(fd);fs.closeSync(fd);fd=undefined;fs.renameSync(temp,p);}
    finally{if(fd!==undefined)fs.closeSync(fd);if(fs.existsSync(temp))fs.unlinkSync(temp);}
  }
  function tx(fn){
    let fd;try{fd=fs.openSync(control+'.lock-'+RUNTIME,'wx',0o600);}catch(e){if(e.code==='EEXIST')return {mutex_busy:true};throw e;}
    try{const c=read(control,{version:1,lease:null,generation_waiters:[],postprocess_waiters:[]});c.generation_waiters??=[];c.postprocess_waiters??=[];const result=fn(c);write(control,c);return result;}
    finally{fs.closeSync(fd);fs.unlinkSync(control+'.lock-'+RUNTIME);}
  }
  const get=id=>read(jobPath(id),null);
  const patch=(id,data)=>{const j=get(id);if(!j)throw new Error('Missing job '+id);const index=read(root+'/executions/'+execution+'.json',null);if(index?.request_id===id&&j.execution_id!==execution)throw new Error('Obsolete worker fenced by recovery.');if(j.cancel_requested&&execution===j.execution_id&&data.status&&data.status!=='deleted')data={...data,status:j.status};Object.assign(j,data,{updated_at:new Date().toISOString()});write(jobPath(id),j);return j;};
  function owned(c,kind){if(c.lease?.owner!==execution||c.lease?.kind!==kind||c.lease.blocked)throw new Error('Comfy reservation is absent or blocked; inspect scheduler before resubmitting.');}
  return {fs,root,jobs,execution,valid,jobPath,read,write,tx,get,patch,owned,control};
})();

const ownershipIndex=S.read(S.root+'/executions/'+S.execution+'.json',null);
if(ownershipIndex&&S.get(ownershipIndex.request_id)?.execution_id!==S.execution)return [];


const cancellationIndex=S.read(S.root+'/executions/'+S.execution+'.json',null);
const cancellationRecord=cancellationIndex?S.get(cancellationIndex.request_id):null;
if(cancellationRecord?.cancel_requested||['deleted','deleting'].includes(cancellationRecord?.status))return [];

const request = $('Prepare Request').first().json;
const uploadedImage = $('Upload Image').first().json;
const template = $input.first().json.template;

if (!template || typeof template !== "object" || template.nodes) {
  throw new Error("ltx.json must be exported in API format.");
}

const workflow = JSON.parse(JSON.stringify(template));

const expectedNodes = {
  "395": "LoadImage",
  "398:376": "PrimitiveStringMultiline",
  "398:373": "CLIPTextEncode",
  "398:362": "PrimitiveInt",
  "398:339": "RandomNoise",
  "75": "SaveVideo"
};

for (const [id, type] of Object.entries(expectedNodes)) {
  if (workflow[id]?.class_type !== type) {
    throw new Error(`Node ${id} is missing or is not ${type}.`);
  }
}

if (!uploadedImage.name || uploadedImage.type !== "input") {
  throw new Error("Comfy did not confirm the image upload.");
}

const imagePath = uploadedImage.subfolder
  ? `${uploadedImage.subfolder}/${uploadedImage.name}`
  : uploadedImage.name;

workflow["395"].inputs.image = imagePath;
workflow["398:376"].inputs.value = request.prompt;
workflow["398:373"].inputs.text = request.negative_prompt;
workflow["398:362"].inputs.value = request.duration_seconds;
workflow["398:339"].inputs.noise_seed = request.seed;

workflow["75"].inputs.filename_prefix =
  `video/n8n/${request.request_id}/ltx`;

// BEGIN ASPECT SELECTOR: fixed 2MP, existing half-resolution generation chain.
if(request.aspect_ratio!==undefined){
  if(!['9:16','16:9'].includes(request.aspect_ratio))throw new Error('Invalid aspect_ratio.');
  if(workflow['403']?.class_type!=='ResolutionSelector')throw new Error('Expected ResolutionSelector node 403. Export the current ltx.json before adapting node IDs.');
  const paths=[['398:372','PrimitiveInt','value','403',0],['398:360','PrimitiveInt','value','403',1],
    ['398:353','ComfyMathExpression','values.a','398:372',0],['398:355','ComfyMathExpression','values.a','398:360',0],
    ['398:356','EmptyLTXVLatentVideo','width','398:353',1],['398:356','EmptyLTXVLatentVideo','height','398:355',1]];
  for(const [id,type,input,source,slot] of paths){
    const link=workflow[id]?.inputs?.[input];
    if(workflow[id]?.class_type!==type||!Array.isArray(link)||link[0]!==source||link[1]!==slot)throw new Error('LTX dimension path mismatch at '+id+'. No generation submitted.');
  }
  for(const id of ['398:353','398:355'])if(String(workflow[id].inputs.expression).replace(/\s/g,'')!=='floor(a/64)*32')throw new Error('Expected half-resolution expression at '+id+'.');
  workflow['403'].inputs.aspect_ratio=request.aspect_ratio==='16:9'?'16:9 (Widescreen)':'9:16 (Portrait Widescreen)';
  workflow['403'].inputs.megapixels=2;
  workflow['403'].inputs.multiple=32;
}
// END ASPECT SELECTOR

return [{
  json: {
    prompt: workflow,
    client_id: `n8n-${request.request_id}`
  }
}];

