const ownershipIndex=S.read(S.root+'/executions/'+S.execution+'.json',null);
if(ownershipIndex&&S.get(ownershipIndex.request_id)?.execution_id!==S.execution)return [];


const cancellationIndex=S.read(S.root+'/executions/'+S.execution+'.json',null);
const cancellationRecord=cancellationIndex?S.get(cancellationIndex.request_id):null;
if(cancellationRecord?.cancel_requested||['deleted','deleting'].includes(cancellationRecord?.status))return [];

// A history GET may fail while Comfy is busy; never resubmit a GPU stage here.
const pollBase=$('Initialize LTX Tracking').first().json;
const pollData=$input.first().json;
const pollNow=Date.now();
if(pollNow-pollBase.tracking_started_at > 24 * 60 * 60 * 1000)throw new Error('LTX monitoring deadline exceeded. No stage was resubmitted. Inspect Comfy before recovery.');
const pollState=S.tx(()=>{
 const j=S.get(pollBase.request_id);
 if(!j||String(j.execution_id)!==S.execution||j.cancel_requested||['cancelled','deleted','deleting','recovering'].includes(j.status))return {obsolete:true};
 const bad=!pollData||typeof pollData!=='object'||Array.isArray(pollData)||pollData.error!==undefined;
 if(!bad){
   if(j.history_poll)S.patch(j.request_id,{history_poll:null});
   return {ready:true};
 }
 const error=pollData?.error;
 const detail=String(typeof error==='string'?error:error?.message??pollData?.message??'Malformed history response').slice(0,600);
 const status=Number(error?.httpCode??error?.statusCode??pollData?.statusCode??0);
 const transient=[408,429,500,502,503,504].includes(status)||
   /timeout|timed out|connection was aborted|ECONNABORTED|ECONNRESET|ECONNInitialize LTX TrackingUSED|ETIMEDOUT|EPIPE|EAI_AGAIN|ENOTFOUND|socket hang up|temporarily unavailable|service unavailable|bad gateway|gateway timeout|(?:status code|code:)\s*(?:408|429|5[0-9]{2})/i.test(detail);
 if(!transient)return {fatal:'LTX history read failed: '+detail};
 const same=j.history_poll?.stage==='ltx'&&j.history_poll?.execution_id===S.execution&&j.history_poll?.prompt_id===pollBase.prompt_id;
 const previous=same?j.history_poll:null;
 const failure={stage:'ltx',execution_id:S.execution,prompt_id:pollBase.prompt_id,unavailable:true,
   first_failure_at:previous?.first_failure_at??pollNow,failures:(previous?.failures??0)+1,last_failure_at:pollNow,detail};
 S.patch(j.request_id,{history_poll:failure});
 if(failure.failures>=6||pollNow-failure.first_failure_at>=300000)return {fatal:'LTX history remains unavailable after '+failure.failures+' failed checks. No stage was resubmitted. Inspect Comfy before recovery. Last error: '+detail};
 return {pending:true};
});
if(pollState.obsolete)return [];
if(pollState.fatal)throw new Error(pollState.fatal);
if(pollState.pending||pollState.mutex_busy)return [{json:{...pollBase,completed:false,history_unavailable:pollState.pending===true}}];

const job = $('Initialize LTX Tracking').first().json;
const history = $input.first().json;
const entry = history[job.prompt_id];

const pending = () => {
  const elapsed = Date.now() - job.tracking_started_at;

  if (elapsed > 24 * 60 * 60 * 1000) {
    throw new Error(
      `Tracking exceeded 24 hours. Check Comfy before resubmitting. Job: ${job.prompt_id}`
    );
  }

  return [{
    json: {
      ...job,
      completed: false,
      status: "waiting_for_completion"
    }
  }];
};

// History can be empty while the job is queued or running.
if (!entry) {
  return pending();
}

const status = entry.status ?? {};
const messages = status.messages ?? [];

const failure = messages.find(message =>
  ["execution_error", "execution_interrupted"].includes(message[0])
);

if (status.status_str === "error" || failure) {
  const detail = failure?.[1]?.exception_message
    ?? failure?.[0]
    ?? "Unknown execution error";

  throw new Error(`LTX failed: ${detail}`);
}

if (status.completed !== true) {
  return pending();
}

if (status.status_str !== "success") {
  throw new Error(
    `Unexpected completed status: ${status.status_str}`
  );
}

// No seu template, o SaveVideo tem ID 75.
const output = entry.outputs?.["75"] ?? {};
const files = [
  ...(output.images ?? []),
  ...(output.videos ?? [])
];

const video = files.find(file =>
  typeof file.filename === "string" &&
  /\.mp4$/i.test(file.filename) &&
  file.type === "output"
);

if (!video) {
  throw new Error(
    "LTX completed, but no output MP4 was found in SaveVideo node 75."
  );
}

const normalizedSubfolder = (video.subfolder ?? "")
  .replace(/\\/g, "/");

if (normalizedSubfolder !== `video/n8n/${job.request_id}` || !/^ltx_/.test(video.filename)) throw new Error('Unexpected LTX output path.');

const relativePath = [
  normalizedSubfolder,
  video.filename
].filter(Boolean).join("/");

return [{
  json: {
    ...job,
    completed: true,
    status: "ready_for_review",
    video: {
      filename: video.filename,
      subfolder: normalizedSubfolder,
      type: video.type,
      container_path: `/comfy-output/${relativePath}`
    }
  }
}];

