  const old=S.get(base.request_id);
  if(old?.status==='finished'&&old.final_video?.filename===base.final_video?.filename)return {recorded:true};
  S.owned(c,'postprocess');
  S.patch(base.request_id,{status:'finished',final_video:base.final_video,finished_at:new Date().toISOString()});
  c.lease=null;
  return {recorded:true};
});
return [{json:{...base,recorded:result.recorded===true}}];

